+std::unique_ptr<Benchmark> Benchmark::clone(const fs::path& workingDirectory) {
+  std::string bitcode;
+  llvm::raw_string_ostream ss(bitcode);
+
+  module()->print(ss);
+
+  return std::make_unique<Benchmark>(name(), bitcode, dynamicConfigProto_, workingDirectory);
+}
